/* C API of the Mojo port of `src/facade.c`, generated by mojo-anything. */
#ifndef FACADE_MOJO_H
#define FACADE_MOJO_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

long parse_long(const char *text, int base);
int parse_int(const char *text);
double parse_double(const char *text);
size_t span(const char *text, const char *accept);
int compare(const char *a, const char *b);
int is_alpha(int c);
int is_space(int c);
int is_punct(int c);
int to_upper(int c);

/* The same functions under `mojo_anything_` names, for shadow runs. */
long mojo_anything_parse_long(const char *text, int base);
int mojo_anything_parse_int(const char *text);
double mojo_anything_parse_double(const char *text);
size_t mojo_anything_span(const char *text, const char *accept);
int mojo_anything_compare(const char *a, const char *b);
int mojo_anything_is_alpha(int c);
int mojo_anything_is_space(int c);
int mojo_anything_is_punct(int c);
int mojo_anything_to_upper(int c);

#endif /* FACADE_MOJO_H */
